<?php
function journey_slug(string $text): string {
    $text = strtolower(trim($text)); $text = iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $text) ?: $text;
    $text = preg_replace('/[^a-z0-9]+/', '-', $text) ?: ''; return trim($text, '-');
}
$act = post_action();
if ($act !== null && !in_array($act, ['save_journey','delete_journey'], true)) back('journey','err','Aksi tidak valid.');
if ($act === 'delete_journey') { $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT); if(!$id||$id<1)back('journey','err','ID Journey tidak valid.'); q('UPDATE journey SET deleted_at=? WHERE id=? AND deleted_at IS NULL',[now(),$id]); audit('delete_journey','#'.$id); back('journey','ok','Journey dihapus.'); }
if ($act === 'save_journey') {
    $id=filter_var($_POST['id']??'0',FILTER_VALIDATE_INT); if($id===false||$id<0)back('journey','err','ID Journey tidak valid.');
    $yearRaw=v_str($_POST['year']??'',1,20); $title=v_str($_POST['title']??'',1,190); $body=v_str($_POST['body']??'',1,1000); $html=v_str($_POST['body_html']??'',0,20000); $status=$_POST['status']??'draft'; $link=v_url($_POST['link_url']??'',['http','https'],true);
    $year = $yearRaw !== null && preg_match('/^\d{4}$/D',$yearRaw) ? (int)$yearRaw : 0;
    if(!$year||$year<2000||$year>(int)date('Y')+1||!$title||!$body||!in_array($status,['draft','published'],true)||($link===null&&($_POST['link_url']??'')!==''))back('journey','err','Tahun, judul, teks, status, atau tautan tidak valid.');
    $html=sanitize_rich_html((string)$html);
    $existing=$id?q_one('SELECT cover_url, document_url, link_url FROM journey WHERE id=? AND deleted_at IS NULL',[$id]):null; $cover=$existing['cover_url']??''; $document=$existing['document_url']??'';
    $oldCover=$cover; $oldDocument=$document;
    try {
        if(!empty($_FILES['cover_file']['name']))$cover=store_content_upload($_FILES['cover_file'],'image');
        if(!empty($_FILES['document_file']['name']))$document=store_content_upload($_FILES['document_file'],'file');
    } catch(RuntimeException $ex){back('journey','err',$ex->getMessage());}
    $slug=v_str($_POST['slug']??'',0,200); $slug=journey_slug($slug?:$title.'-'.$year); if(!$slug||strlen($slug)>200)back('journey','err','Slug tidak dapat dibuat.');
    $check=q_one('SELECT id FROM journey WHERE slug=? AND deleted_at IS NULL AND id<>?',[$slug,$id?:0]); if($check)back('journey','err','Slug Journey sudah digunakan.');
    try {
        if($id){q('UPDATE journey SET year=?,title=?,body=?,body_html=?,slug=?,cover_url=?,document_url=?,link_url=?,status=?,updated_at=? WHERE id=? AND deleted_at IS NULL',[(string)$year,$title,$body,$html?:null,$slug,$cover,$document,$link?:'', $status,now(),$id]);audit('update_journey','#'.$id);}else{$sort=(int)q_val('SELECT COALESCE(MAX(sort_order),0)+10 FROM journey WHERE deleted_at IS NULL');q('INSERT INTO journey (year,title,body,body_html,slug,cover_url,document_url,link_url,status,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)',[(string)$year,$title,$body,$html?:null,$slug,$cover,$document,$link?:'', $status,$sort]);audit('create_journey','#'.db()->lastInsertId());}
    } catch(Throwable $ex) { back('journey','err','Journey gagal disimpan.'); }
    foreach([[$oldCover,$cover],[$oldDocument,$document]] as $replacement) {
        $old=$replacement[0]; $new=$replacement[1];
        if($old!==''&&$old!==$new&&strpos($old,'assets/uploads/')===0){$file=APP_ROOT.'/'.$old;if(is_file($file))@unlink($file);}
    }
    back('journey','ok','Journey tersimpan.');
}
layout_head('Journey','journey'); $editId=filter_var($_GET['edit']??'0',FILTER_VALIDATE_INT); $edit=$editId&&$editId>0?q_one('SELECT * FROM journey WHERE id=? AND deleted_at IS NULL',[$editId]):null; $src=$edit?:['year'=>'','title'=>'','body'=>'','body_html'=>'','slug'=>'','cover_url'=>'','document_url'=>'','link_url'=>'','status'=>'draft'];
echo '<div class="card"><div class="section-heading"><div><p class="muted">Dokumentasi tahunan</p><h2>'.($edit?'Edit dokumentasi':'Tambah dokumentasi').'</h2></div></div><form method="post" enctype="multipart/form-data" class="fields">'.csrf_field().'<input type="hidden" name="action" value="save_journey"><input type="hidden" name="id" value="'.(int)($src['id']??0).'"><label>Tahun<input name="year" required maxlength="20" value="'.e($src['year']).'" placeholder="2025"></label><label>Judul<input name="title" required maxlength="190" value="'.e($src['title']).'"></label><label>Slug<input name="slug" maxlength="200" value="'.e($src['slug']).'" placeholder="2025-proyek-pertama"></label><label>Status<select name="status"><option value="draft"'.($src['status']==='draft'?' selected':'').'>Draft</option><option value="published"'.($src['status']==='published'?' selected':'').'>Published</option></select></label><label class="full">Ringkasan<textarea name="body" required maxlength="1000" rows="4">'.e($src['body']).'</textarea></label><label class="full">Dokumentasi rich text<div class="rich-toolbar" aria-label="Format teks"><button type="button" data-command="bold"><strong>B</strong></button><button type="button" data-command="italic"><em>I</em></button><button type="button" data-command="heading">Judul</button><button type="button" data-command="insertUnorderedList">Daftar</button><button type="button" data-command="link">Tautan</button></div><div class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true">'.($src['body_html']? $src['body_html']:'').'</div><textarea class="sr-only" name="body_html" rows="1">'.e($src['body_html']?:'').'</textarea></label><label>Gambar cover<input type="file" name="cover_file" accept="image/jpeg,image/png,image/gif,image/webp"></label><label>Dokumen pendukung<input type="file" name="document_file" accept="application/pdf">'.($src['document_url']?'<span class="muted">PDF saat ini: '.e($src['document_url']).'</span>':'').'</label><label class="full">Tautan dokumentasi<input type="url" name="link_url" maxlength="1000" value="'.e($src['link_url']).'" placeholder="https://..."></label><div class="full editor-actions"><button class="btn" type="submit" data-confirm="Simpan dokumentasi Journey ini?">Simpan Journey</button>'.($edit?' <a class="btn sec" href="index.php?p=journey">Batal edit</a>':'').'</div></form></div>'; 
echo '<div class="card"><div class="section-heading"><div><p class="muted">Daftar</p><h2>Journey menurut tahun</h2></div></div>'; $rows=q_all('SELECT id,year,title,status,slug FROM journey WHERE deleted_at IS NULL ORDER BY year DESC, sort_order,id DESC'); if(!$rows)echo '<div class="empty-state"><strong>Belum ada Journey</strong><p>Tambahkan dokumentasi pertama dengan tahun dan judul.</p></div>'; else{echo '<table><thead><tr><th>Publikasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>';foreach($rows as$r){echo '<tr><td><strong>#/'.e($r['year']).'</strong><br>'.e($r['title']).'<br><span class="muted">/'.e($r['slug']).'</span></td><td><span class="pill '.($r['status']==='published'?'pub':'').'">'.e($r['status']).'</span></td><td><div class="row-actions"><a class="btn sm sec" href="index.php?p=journey&edit='.(int)$r['id'].'">Edit</a><form method="post">'.csrf_field().'<input type="hidden" name="action" value="delete_journey"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="btn sm danger" type="submit" data-confirm="Hapus Journey ini?">Hapus</button></form></div></td></tr>';}} echo '</tbody></table></div>'; layout_foot();
